import{z as p,x as B,o as i,c as A,q as e,j as n,D as o,d as l,s,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"logit 软上限","description":"","frontmatter":{"title":"logit 软上限","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/logit-softcap.md","filePath":"llm/logit-softcap.md","lastUpdated":1791063341000}'),c={name:"llm/logit-softcap.md"};function m(d,a,g,h,f,D){const E=B("Mermaid");return i(),A("div",null,[a[2]||(a[2]=e('<h1 id="logit-软上限" tabindex="-1">logit 软上限 <a class="header-anchor" href="#logit-软上限" aria-label="Permalink to &quot;logit 软上限&quot;">​</a></h1><div class="epigraph"><p>采样前给每个 logit 套一道 tanh 软上限：越界的信号被压弯而不是剪断——模型话痨与复读，往往是一个没封顶的 logit 闹的。</p><footer>—— 据 Gemma 2 技术报告（2024）final logit softcap；Grok 与 SilasTron 实现</footer></div><p><a href="/llm/qk-clip">QK-Clip</a> 在训练期给注意力 logit 动手术，本课在推理与输出侧给最终 logits 上护栏。缺口是 <strong>logit 软上限</strong>：\\(c\\cdot\\tanh(l/c)\\) 把无界 logit 压进 \\((-c,c)\\)——大值压弯、小值不动。它是 Gemma 2 稳定训练与改善采样的公开秘方之一。本课不进 logits 后处理的采样链（top-p/min-p 各有专课）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最终层 logit 本质无界：异常激活（重复 token、对抗前后缀）会让某 token 的 logit 冲到几十甚至上百，softmax 后概率逼近 1——模型进入复读或退化输出；fp16 下还会数值溢出。硬截断（clip 到 ±c）在边界造成梯度死区；温度缩放则压不平「正常分布与异常峰」的双重需求。缺口：<strong>平滑压顶</strong>。</p><p><span class="marginnote">术语翻译：softcap = \\(c\\cdot\\tanh(l/c)\\)，\\(c\\) 是上限常数（Gemma 2 输出层用 30）；「软」在 tanh 的渐近——logit 无限大时输出趋近 \\(c\\) 但永不过界，梯度 \\(1-\\tanh^2\\) 平滑归零而非硬归零。</span></p><p><span class="marginnote">数字实例：\\(c=30\\)。正常 logit 5 → \\(30\\tanh(1/6)\\approx 4.9\\)（几乎不动）；异常 logit 80 → \\(30\\tanh(8/3)\\approx 29.6\\)（压到界内）；softmax 里 29.6 与 4.9 的差距 \\(\\approx 24.7\\)，仍保区分度但不再是「100 分 vs 0 分」的暴政。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两处可选挂点：<strong>最终 logits</strong>（Gemma 2 的用法，控采样与训练稳定性）与<strong>注意力 QK logits</strong>（Gemma 2 同时在每层注意力用 50 的 cap，与 QK-Clip 形成对照方案）。实现一行：<code>logits = cap * tanh(logits / cap)</code>；训练推理同用，无状态开销。与温度的关系：cap 先行、temperature 后行——先封顶再缩放，两层护栏各司其职。</p>',9)),(i(),n(r,null,{default:o(()=>[s(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8E%9F%E5%A7%8B%20logit%20l%22%5D%20--%3E%20B%5B%22c%C2%B7tanh(l%2Fc)%22%5D%0A%20%20B%20--%3E%20C%7B%22%7Cl%7C%20vs%20c%22%7D%0A%20%20C%20--%3E%7C%22%E5%B0%8F%22%7C%20D%5B%22%E8%BF%91%E4%BC%BC%E7%BA%BF%E6%80%A7%3A%20%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20C%20--%3E%7C%22%E5%A4%A7%22%7C%20E%5B%22%E6%B8%90%E8%BF%91%E5%8E%8B%E5%90%91%20%C2%B1c%22%5D%0A%20%20D%20--%3E%20F%5B%22softmax%20%E5%90%8E%E9%87%87%E6%A0%B7%22%5D%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%20G%5B%22%E6%97%A0%E6%BA%A2%E5%87%BA%20%2F%20%E6%97%A0%E5%A4%8D%E8%AF%BB%E6%9A%B4%E6%94%BF%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"直觉类比：像给音轨加 limiter（限幅器）而非剪切——正常音量原样通过，爆音被柔性压扁但保留轮廓；硬 clip 是「过阈全剪」，听感发劈（梯度死区），limiter 是「过阈弯腰」，动态还在。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[l("为什么 tanh 是对的形状：它是有界、奇函数、原点线性（\\(\\tanh(x)\\approx x\\)）——三个性质分别给出「有上界」「保序」「小信号不扰动」。训练侧的收益来自两点："),t("strong",null,"数值稳定"),l("（logit 有界则交叉熵的指数项不再溢出，fp16 友好）；"),t("strong",null,"梯度健康"),l("（越界 logit 的梯度被 \\(1-\\tanh^2\\) 自然衰减，重复循环里的「自我强化」路径被削弱——复读本质是 logit 正反馈）。代价是精度损失：cap 过小会把排序压平（softmax 分辨力下降），\\(c=30\\) 量级下实测对损失的影响在 0.5% 内，Gemma 2 用它换到了更大的 batch 稳定域。")],-1)),(i(),n(r,null,{default:o(()=>[s(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%BA%E4%BD%95%E9%80%89%20tanh%3F%22%7D%20--%3E%20R%5B%22%E6%9C%89%E7%95%8C%3A%20%E6%95%B0%E5%80%BC%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20Q%20--%3E%20S%5B%22%E5%A5%87%E5%87%BD%E6%95%B0%3A%20%E4%BF%9D%E5%BA%8F%E4%B8%8D%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20Q%20--%3E%20T%5B%22%E5%8E%9F%E7%82%B9%E7%BA%BF%E6%80%A7%3A%20%E5%B0%8F%E4%BF%A1%E5%8F%B7%E9%9B%B6%E6%8D%9F%22%5D%0A%20%20U%7B%22%E5%A4%8D%E8%AF%BB%E6%80%8E%E4%B9%88%E8%A2%AB%E6%B2%BB%3F%22%7D%20--%3E%20V%5B%22%E9%87%8D%E5%A4%8D%20logit%20%E6%AD%A3%E5%8F%8D%E9%A6%88%22%5D%0A%20%20V%20--%3E%20W%5B%22%E8%B6%8A%E7%95%8C%E9%83%A8%E5%88%86%E6%A2%AF%E5%BA%A6%E8%A1%B0%E5%87%8F%22%5D%0A%20%20W%20--%3E%20X%5B%22%E8%87%AA%E5%BC%BA%E5%8C%96%E5%9B%9E%E8%B7%AF%E8%A2%AB%E5%89%8A%E5%BC%B1%22%5D%0A%20%20T%20--%3E%20Y%5B%22%E8%AE%AD%E7%BB%83%E6%8E%A8%E7%90%86%E5%90%8C%E7%94%A8%22%5D%0A%20%20X%20--%3E%20Y%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=e('<p><span class="marginnote">常见误区：把 softcap 当成采样参数乱调——\\(c\\) 是模型训练时定死的架构常数，推理时另换 \\(c\\) 会让模型处于「训练时没见过」的分布；另一误区是与 min-p/top-p 叠加过猛——cap 已把暴政峰压平，再叠多层截断会把长尾掐死，输出趋向无聊。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Cap 改变模型的概率分布——训练时不用、推理时用的「半路 cap」是分布漂移；反之亦然。对 cap 的替代方案：logit 归一化（除以范数）、注意力侧的 QK-norm 与 <a href="/llm/qk-clip">QK-Clip</a>（训练期手术）——工程界当前偏好「训练期根治，推理期不设防」，softcap 是训练期根治族里最廉价的一员。适用性：从零预训的模型直接内置；拿开源模型做推理时，若它没内置 cap，别自己加——先试重复惩罚与 <a href="/llm/speculative-decoding">min-p 类采样修正</a>同族的推理侧工具。</p><p><span class="marginnote">直觉类比：cap 是「出厂限速器」——发动机（模型）造好时限速 30，正常驾驶无感，失控踩死油门也顶到限速；事后自己改装限速器（推理时加 cap），等于让出厂调校作废，先查原厂手册。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(c\\cdot\\tanh(l/c)\\)：有界、保序、小信号无损，一行代码。</li><li>训练推理必须同用，\\(c\\) 是架构常数不是采样旋钮。</li><li>治复读靠削弱 logit 正反馈；治溢出靠有界化。</li><li>出处：Gemma 2 技术报告 2024；Grok/SilasTron 开源实现；QK-Clip 2025 对照。</li></ul>',6))])}const u=p(c,[["render",m]]);export{F as __pageData,u as default};
